 prior=old.get(d['id']);a={'manifest':n,'id':d['id'],'name':d['name'],'inputSha256':hashlib.sha256(raw).hexdigest(),'acceptedFaculty':prior is not None,'priorRoles':len(prior['jobs']) if prior else 0,'reviewedRoles':len(d['jobs'])}
