 a['disposition']='Reviewed replacement of existing faculty history; no new person.';audit.append(a);replacements.append({'id':r['id'],'priorSha256':hashobj(prior),'priorHashContract':'SHA256 of UTF-8 JSON with ensure_ascii=false and separators comma/colon, insertion-order keys','manifestNumber':n,'replacement':r})
